        public static int Count { get { return B64.Count; } }

        private static readonly Dictionary<string, BitmapImage> Cache = new Dictionary<string, BitmapImage>(StringComparer.OrdinalIgnoreCase);
        private static readonly object Sync = new object();

        public static BitmapImage Get(string iso2, int width = 40)
        {
            if (string.IsNullOrEmpty(iso2)) iso2 = "un";
            iso2 = iso2.ToUpperInvariant();
            lock (Sync)
            {
                BitmapImage cached;
                if (Cache.TryGetValue(iso2, out cached)) return cached;
                string b64;
                if (!B64.TryGetValue(iso2, out b64))
                {
                    if (!B64.TryGetValue("UN", out b64)) return null;
                }
                try
                {
                    byte[] bytes = Convert.FromBase64String(b64);
                    var bmp = new BitmapImage();
                    bmp.BeginInit();
                    bmp.StreamSource = new MemoryStream(bytes);
                    bmp.CacheOption = BitmapCacheOption.OnLoad;
                    bmp.CreateOptions = BitmapCreateOptions.PreservePixelFormat;
                    bmp.EndInit();
                    bmp.Freeze();
                    Cache[iso2] = bmp;
                    return bmp;
                }
                catch { return null; }
            }
        }
    }
